// ===== CONFIGURA AQUÍ =====
// Remitentes permitidos (como aparecen en el campo "from" del reenviador). Vacío = acepta todos.
// Ej: ['BDV', 'Banesco', '2662', '88232']
const REMITENTES_PERMITIDOS = [];
// ==========================

function interpretarSMS(texto, remitente) {
  const t = String(texto || '').replace(/\s+/g, ' ').trim();
  const r = { parseado: false, motivo: '', texto: t };
  if (!t) { r.motivo = 'sms_vacio'; return r; }

  if (REMITENTES_PERMITIDOS.length && !REMITENTES_PERMITIDOS.some(x => String(remitente || '').toLowerCase().includes(String(x).toLowerCase()))) {
    r.motivo = 'remitente_no_permitido'; return r;
  }

  // SOLO dinero que ENTRA. Se descartan pagos que tú envías, débitos, compras, etc.
  const SALIDA = /(realizaste|enviaste|has enviado|pagaste|transferiste|debito|débito|cargo|compra|retiro|consumo|cobro de comisi)/i;
  const ENTRADA = /(recibiste|has recibido|te (?:envi[oó]|pag[oó]|transfiri[oó])|abono|acreditad|cr[eé]dito|pago m[oó]vil recibido|recibido)/i;
  if (SALIDA.test(t)) { r.motivo = 'movimiento_de_salida'; return r; }
  if (!ENTRADA.test(t)) { r.motivo = 'no_es_ingreso'; return r; }

  // Monto: 'Bs. 1.234,56' | 'Bs.374,25' | 'Bs 374.25' | 'VES 374,25' | '374,25 Bs'
  const mMonto = t.match(/(?:Bs\.?\s?S?\.?|VES|VEF)\s*:?\s*(\d{1,3}(?:[.,]\d{3})*(?:[.,]\d{1,2})?|\d+(?:[.,]\d{1,2})?)/i)
              || t.match(/(\d{1,3}(?:[.,]\d{3})*(?:[.,]\d{1,2})?|\d+(?:[.,]\d{1,2})?)\s*(?:Bs\.?|VES)/i);
  // Referencia: 'Ref: 001234567890' | 'Ref.12345678' | 'Referencia 123456' | 'Nro. 987654321' | 'Operacion 123456'
  const mRef = t.match(/(?:ref(?:erencia)?|n(?:ro|[uú]mero)|operaci[oó]n|comprobante)\.?\s*(?:de\s+)?(?:operaci[oó]n\s*)?[:#]?\s*(\d{6,20})/i);
  if (!mMonto) { r.motivo = 'sin_monto'; return r; }
  if (!mRef) { r.motivo = 'sin_referencia'; return r; }

  const monto = normalizarMonto(mMonto[1]);
  if (!(monto > 0)) { r.motivo = 'monto_invalido'; return r; }

  const mTel = t.match(/\b(0?4(?:12|14|16|24|26|22)[-\s]?\d{3}[-\s]?\d{4})\b/);
  return {
    parseado: true,
    metodo: 'pago_movil',
    referencia: mRef[1],
    monto,
    pagador: mTel ? mTel[1].replace(/\D/g, '') : null,
    raw: t.slice(0, 1000)
  };
}

// '1.234,56' -> 1234.56 | '1,234.56' -> 1234.56 | '374,25' -> 374.25 | '374.25' -> 374.25 | '1.234' -> 1234
function normalizarMonto(s) {
  s = String(s);
  const ultPunto = s.lastIndexOf('.'), ultComa = s.lastIndexOf(',');
  const sep = Math.max(ultPunto, ultComa);
  if (sep === -1) return Number(s);
  const decimales = s.length - sep - 1;
  if (decimales === 3 && (ultPunto === -1 || ultComa === -1)) return Number(s.replace(/[.,]/g, '')); // solo miles
  return Number(s.slice(0, sep).replace(/[.,]/g, '') + '.' + s.slice(sep + 1));
}

// ===== Entrada del webhook =====
// Acepta los formatos de las apps reenviadoras más comunes (JSON o formulario).
const item = $input.first().json;
const b = item.body && typeof item.body === 'object' ? item.body : item;
const texto = b.texto ?? b.message ?? b.text ?? b.msg ?? b.sms ?? b.content ?? b.body ?? '';
const remitente = b.remitente ?? b.from ?? b.sender ?? b.number ?? '';
const res = interpretarSMS(typeof texto === 'string' ? texto : JSON.stringify(texto), remitente);
// Hora de recepción del servidor (no la del celular, que puede venir desfasada o en otro formato)
if (res.parseado) res.ocurrido_at = new Date().toISOString();
return [{ json: res }];
